            kiln_val call_result_val = KILN_VAL_UNDEFINED;
            status = kiln_c99_call_val(host, &call_result_val, kiln_val_from_boundary(args[0]),
                                       kiln_val_from_boundary(args[1]),
                                       list->count == 0 ? NULL : list->elements, list->count, depth,
                                       thrown);
